import{z as o,x as s,o as B,c as p,q as A,j as n,D as t,d as E,s as l,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"尾部对冲的组合","description":"","frontmatter":{"title":"尾部对冲的组合","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/pf-tail-hedging.md","filePath":"quant/pf-tail-hedging.md","lastUpdated":1791413859000}'),h={name:"quant/pf-tail-hedging.md"};function d(u,a,m,c,f,D){const r=s("Mermaid");return B(),p("div",null,[a[2]||(a[2]=A('<h1 id="尾部对冲的组合" tabindex="-1">尾部对冲的组合 <a class="header-anchor" href="#尾部对冲的组合" aria-label="Permalink to &quot;尾部对冲的组合&quot;">​</a></h1><div class="epigraph"><p>尾部对冲是用确定的负 carry 去买一份或有的大额赔付；它的会计期不是季度，是危机日。</p><footer>—— 据 Daniel and Moskowitz, Momentum Crashes, Journal of Financial Economics, 2016；Taleb, The Black Swan, 2007 整理</footer></div><p><a href="/quant/pf-multiasset">上一课</a>把多资产写成分散宏观环境的组合；但有一类风险分散不掉——所有风险资产共享的左尾。组件的课已有：<a href="/quant/tail-risk-factor">尾部风险因子</a>、<a href="/quant/short-vol-tail">波动率卖方与尾部</a>、<a href="/quant/gap-risk">缺口风险</a>、<a href="/quant/momentum-crash">动量崩溃</a>。本课写它们如何进组合：预算多少、买哪种凸性、以及怎么验收「对冲了」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>尾部对冲是三个决定，每个都有对称的死法。其一，预算：每年烧多少 carry？<span class="marginnote">carry 在这里指持有对冲仓位的持续成本：虚值 put 每年付的保费、VIX 期货展期的损耗，平时像漏水一样把收益滴走。直觉类比：给房子买的火险——绝大多数年份保费白白交出去，换的是火灾那天的大额赔付。</span>太少，危机日对冲抵不掉左尾，徒增复杂度；太多，保费把长期收益吃穿，组合变成对冲卖方的补贴客户。其二，工具：静态期权（虚值 put 及其价差）、波动率工具（VIX 期货与期权，带展期损耗，见 <a href="/quant/vol-etp-rebalance-flow">Vol ETP 每日再平衡流</a>）、动态凸性（趋势与波动目标）——三者的凸性形状、基差与容量都不同，混在「对冲」一个词下会算错账。其三，验收：历史回测里「恰好」覆盖 2008 与 2020 的对冲组合，大概率是对那两次危机的过拟合——对冲的历史样本太薄，不足以支撑一次普通的样本外声明。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是把尾部对冲做成一个三段的预算问题：先把可容忍的 carry 拖累写成硬约束、交给优化器反解对冲腿规模；再按凸性性质把工具菜单分组、各组单独记 carry 的账；最后用三道互不替代的检验验收。预算随体制时变，但调整规则必须事先写定并与压力测试联测。全过程的纪律是一句话：对冲的每个数字都要同时出现在保费表与赔付表上。</p><h3 id="预算与菜单" tabindex="-1">预算与菜单 <a class="header-anchor" href="#预算与菜单" aria-label="Permalink to &quot;预算与菜单&quot;">​</a></h3><p>预算当政策变量：把尾部损失容忍写成约束——<a href="/quant/cvar-opt">CVaR 优化</a>或<a href="/quant/drawdown-constrained-opt">回撤约束优化</a>——让优化器反解对冲腿的规模，而不是拍脑袋一个百分比。菜单按性质分组：静态期权凸性成本明确（premium 与到期），行权价与期限是设计参数；动态凸性（<a href="/quant/cta-tsmom">cta-tsmom</a> 的危机 alpha、<a href="/quant/vol-targeting">波动目标</a>的自动减仓）不付保费、付的是震荡市里的磨损与换手；<span class="marginnote">「动态凸性」就是不花钱买保险、而用规则制造凸性：波动从 15% 升到 30% 时，波动目标自动把仓位砍半，等于跌势里自动轻仓。它不付保费，付的是震荡市里反复进出被磨损——保险费换了一种形式，照样在支付。</span>波动率工具介于两者之间，展期损耗是固定负 carry。验收走三道：极值口径检查左尾形状（<a href="/quant/evt">极值理论 EVT</a>）；情景库打分（下一课的对象）；以及最容易被略过的一道——账户可行性：对冲赔付与主组合的保证金追缴是否同时发生、赔付到账时你是否还有抵押品活着用它（<a href="/quant/gap-risk">缺口风险</a>的时间维度）。</p>',9)),(B(),n(i,null,{default:t(()=>[l(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20BUD%5B%22%E5%B0%BE%E9%83%A8%E9%A2%84%E7%AE%97%EF%BC%9A%E5%8F%AF%E5%AE%B9%E5%BF%8D%E7%9A%84%20carry%20%E6%8B%96%E7%B4%AF%22%5D%20--%3E%20MENU%5B%22%E5%87%B8%E6%80%A7%E8%8F%9C%E5%8D%95%EF%BC%9A%E9%9D%99%E6%80%81%E6%9C%9F%E6%9D%83%2F%E6%B3%A2%E5%8A%A8%E7%8E%87%E5%B7%A5%E5%85%B7%2F%E5%8A%A8%E6%80%81%E5%87%B8%E6%80%A7%22%5D%0A%20%20MENU%20--%3E%20TRIG%5B%22%E4%BD%93%E5%88%B6%E4%B8%8E%E8%A7%A6%E5%8F%91%EF%BC%9A%E6%97%B6%E5%8F%98%E9%A2%84%E7%AE%97%22%5D%0A%20%20TRIG%20--%3E%20TEST1%5B%22%E5%B7%A6%E5%B0%BE%E5%BD%A2%E7%8A%B6%EF%BC%9AEVT%20%E5%8F%A3%E5%BE%84%22%5D%0A%20%20TRIG%20--%3E%20TEST2%5B%22%E6%83%85%E6%99%AF%E5%BA%93%E6%89%93%E5%88%86%22%5D%0A%20%20TRIG%20--%3E%20TEST3%5B%22%E8%B4%A6%E6%88%B7%E5%8F%AF%E8%A1%8C%E6%80%A7%EF%BC%9A%E4%BF%9D%E8%AF%81%E9%87%91%E4%B8%8E%E5%88%B0%E8%B4%A6%E6%97%B6%E5%BA%8F%22%5D%0A%20%20TEST1%20--%3E%20BOOK%5B%22%E5%AF%B9%E5%86%B2%E8%B4%A6%E6%9C%AC%E4%B8%8E%E5%B9%B4%E5%BA%A6%E5%A4%8D%E7%9B%98%22%5D%0A%20%20TEST2%20--%3E%20BOOK%0A%20%20TEST3%20--%3E%20BOOK%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("为什么对冲在危机日要打折算账：赔付与亏损的同时性会被结算与保证金打断——深虚 put 在崩盘当天未必有对手价，VIX 期货与现货在极端时刻基差走阔，趋势策略的仓位可能在急反转中先回吐再反手（"),e("a",{href:"/quant/momentum-crash"},"动量崩溃"),E("写的正是收益来源自身的左尾）。所以对冲预算要覆盖"),e("strong",null,"策略的尾部"),E("而不只是资产的尾部：连趋势这种「危机 alpha」也是统计性的，多数危机中有效、快反转型危机中失灵（"),e("a",{href:"/quant/crisis-alpha"},"危机 alpha"),E("），它没有合同义务赔付，也就不该按保险的会计来记。时变预算的另一面是择时风险：按体制调对冲预算（波动与相关的先行指标）能省保费，但调整错误的成本正好落在最痛的时刻——预算的时变规则要与压力测试（下一课）联测，而不是独立微调。")],-1)),(B(),n(i,null,{default:t(()=>[l(r,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20CRASH%5B%22%E5%B4%A9%E7%9B%98%E6%97%A5%EF%BC%9A%E4%B8%BB%E7%BB%84%E5%90%88%E6%B7%B1%E4%BA%8F%22%5D%20--%3E%20P1%5B%22%E6%B7%B1%E8%99%9A%20put%EF%BC%9A%E5%AF%B9%E6%89%8B%E4%BB%B7%E7%BC%BA%E5%A4%B1%EF%BC%8C%E6%88%90%E4%BA%A4%E6%89%93%E6%8A%98%22%5D%0A%20%20CRASH%20--%3E%20P2%5B%22VIX%20%E6%9C%9F%E8%B4%A7%E4%B8%8E%E7%8E%B0%E8%B4%A7%E5%9F%BA%E5%B7%AE%E8%B5%B0%E9%98%94%22%5D%0A%20%20CRASH%20--%3E%20P3%5B%22%E8%B6%8B%E5%8A%BF%E7%AD%96%E7%95%A5%E6%80%A5%E5%8F%8D%E8%BD%AC%EF%BC%8C%E5%85%88%E5%9B%9E%E5%90%90%E5%86%8D%E5%8F%8D%E6%89%8B%22%5D%0A%20%20P1%20--%3E%20CASH%5B%22%E7%BA%B8%E9%9D%A2%E8%B5%94%E4%BB%98%E4%B8%8D%E7%AD%89%E4%BA%8E%E5%8F%AF%E7%94%A8%E7%8E%B0%E9%87%91%22%5D%0A%20%20P2%20--%3E%20CASH%0A%20%20P3%20--%3E%20CASH%0A%20%20CASH%20--%3E%20MARGIN%5B%22%E4%BF%9D%E8%AF%81%E9%87%91%E8%BF%BD%E7%BC%B4%E5%90%8C%E6%97%B6%E5%88%B0%E6%9D%A5%EF%BC%8C%E8%A6%81%E7%94%A8%E6%B4%BB%E7%9D%80%E7%9A%84%E6%8A%B5%E6%8A%BC%E5%93%81%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=A('<p><span class="marginnote">常见误区：以为「组合有对冲」就等于崩盘时对冲腿一定赚钱接得住。实际上深虚 put 可能在最需要流动性的一刻没有买方报价，赔付到账可能比保证金追缴晚一周——验收对冲，验的是这套现金时序，不只是收益曲线。</span></p><p><span class="marginnote">量级锚点：虚值两成的股指 put 单年保费常在名义的百分之几量级，而危机日组合回撤可达三至五成——预算不足的对冲等于没对冲；「历年烧掉的保费」必须与其买到的左尾截断幅度写在同一张表上。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写波动率产品的定价与对冲细节（波动率交易深化课程的对象），不给「必买清单」；<a href="/quant/short-vol-tail">波动率卖方与尾部</a>的另一面——通过卖尾部收保费——是预算的对手盘，不在本课的买入侧。对冲的会计（保证金、结算、抵押品）是约束不是细节：一份纸面完美、现金流程走不通的对冲方案等于零。历史样本稀薄决定了尾部对冲的验收永远是「情景 + 极值 + 账户」三件套，回测夏普在这里没有发言权。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>尾部对冲的三个决定：预算、凸性菜单、验收；每个都有对称的死法（太少无用，太多蚀本）。</li><li>预算写成约束由优化器反解；工具按静态期权、波动率工具、动态凸性分账，carry 性质不同。</li><li>危机日要打折算账：基差、结算与保证金让纸面赔付与可用现金不同时。</li><li>趋势是统计性凸性而非保险；对冲预算要覆盖策略自身的左尾。</li><li>出处：Daniel &amp; Moskowitz, <em>JFE</em>, 2016；Taleb, <em>The Black Swan</em>, 2007；危机 alpha 口径据 CTA 文献整理。</li></ul>',6))])}const C=o(h,[["render",d]]);export{T as __pageData,C as default};
